"""Curated SQLite SQL practice bank: business questions paired with executable SQL."""

QUESTIONS = [
    {"id":"Q01","category":"Portfolio overview","title":"What is the overall claims portfolio?","business_value":"Establish the overall volume and cost baseline.","sql":"SELECT COUNT(*) AS claim_count, COUNT(DISTINCT VehicleID) AS distinct_vehicles, ROUND(SUM(Actual_Repair_Cost_INR), 2) AS total_repair_cost_inr, ROUND(AVG(Actual_Repair_Cost_INR), 2) AS average_repair_cost_inr, MIN(AccidentDate) AS first_accident, MAX(AccidentDate) AS last_accident FROM telematics_claims;"},
    {"id":"Q02","category":"Portfolio overview","title":"How many repeat-incident vehicles are present?","business_value":"Understand repeat vehicle incidents; repeats are not inherently suspicious.","sql":"SELECT COUNT(*) AS vehicles_with_multiple_claims FROM (SELECT VehicleID FROM telematics_claims GROUP BY VehicleID HAVING COUNT(*) > 1);"},
    {"id":"Q03","category":"Vehicle brand","title":"Which brands account for the most claims?","business_value":"Understand portfolio mix and avoid treating raw volume as risk rate.","sql":"SELECT Vehicle_Brand, COUNT(*) AS claim_count, ROUND(100.0 * COUNT(*) / (SELECT COUNT(*) FROM telematics_claims), 2) AS claim_share_pct FROM telematics_claims GROUP BY Vehicle_Brand ORDER BY claim_count DESC;"},
    {"id":"Q04","category":"Vehicle brand","title":"Which brands have the highest average repair cost?","business_value":"Compare claim severity across manufacturers.","sql":"SELECT Vehicle_Brand, COUNT(*) AS claim_count, ROUND(AVG(Actual_Repair_Cost_INR), 2) AS avg_cost_inr, ROUND(SUM(Actual_Repair_Cost_INR), 2) AS total_cost_inr FROM telematics_claims GROUP BY Vehicle_Brand HAVING COUNT(*) >= 20 ORDER BY avg_cost_inr DESC;"},
    {"id":"Q05","category":"Vehicle brand","title":"What share of total repair spend comes from each brand?","business_value":"Find where the largest absolute financial exposure sits.","sql":"SELECT Vehicle_Brand, ROUND(SUM(Actual_Repair_Cost_INR), 2) AS total_cost_inr, ROUND(100.0 * SUM(Actual_Repair_Cost_INR) / (SELECT SUM(Actual_Repair_Cost_INR) FROM telematics_claims), 2) AS cost_share_pct FROM telematics_claims GROUP BY Vehicle_Brand ORDER BY total_cost_inr DESC;"},
    {"id":"Q06","category":"Crash severity","title":"How does impact point relate to repair cost?","business_value":"Quantify repair-cost differences by damaged vehicle zone.","sql":"SELECT Impact_Point, COUNT(*) AS claim_count, ROUND(AVG(Actual_Repair_Cost_INR), 2) AS avg_cost_inr, ROUND(AVG(Speed_At_Impact_kmh), 2) AS avg_impact_speed_kmh, ROUND(100.0 * AVG(Airbag_Deployed), 2) AS airbag_rate_pct FROM telematics_claims GROUP BY Impact_Point ORDER BY avg_cost_inr DESC;"},
    {"id":"Q07","category":"Crash severity","title":"How does airbag deployment relate to repair cost?","business_value":"Study a severity proxy; airbag deployment is not a causal estimate.","sql":"SELECT Airbag_Deployed, COUNT(*) AS claim_count, ROUND(AVG(Speed_At_Impact_kmh), 2) AS avg_speed_kmh, ROUND(AVG(G_Force_Impact), 2) AS avg_g_force, ROUND(AVG(Actual_Repair_Cost_INR), 2) AS avg_cost_inr FROM telematics_claims GROUP BY Airbag_Deployed ORDER BY Airbag_Deployed;"},
    {"id":"Q08","category":"Crash severity","title":"What are repair costs by impact-speed band?","business_value":"Understand the cost curve over increasing impact speeds.","sql":"SELECT CASE WHEN Speed_At_Impact_kmh < 25 THEN '01 Low (<25)' WHEN Speed_At_Impact_kmh < 50 THEN '02 Moderate (25-49)' WHEN Speed_At_Impact_kmh < 80 THEN '03 High (50-79)' ELSE '04 Very high (80+)' END AS speed_band, COUNT(*) AS claim_count, ROUND(AVG(Actual_Repair_Cost_INR), 2) AS avg_cost_inr, ROUND(AVG(G_Force_Impact), 2) AS avg_g_force FROM telematics_claims GROUP BY speed_band ORDER BY speed_band;"},
    {"id":"Q09","category":"Crash severity","title":"How does G-force band relate to average cost?","business_value":"Use impact acceleration as another severity indicator.","sql":"SELECT CASE WHEN G_Force_Impact < 2 THEN '01 <2g' WHEN G_Force_Impact < 4 THEN '02 2-4g' WHEN G_Force_Impact < 7 THEN '03 4-7g' ELSE '04 7g+' END AS g_force_band, COUNT(*) AS claim_count, ROUND(AVG(Speed_At_Impact_kmh), 2) AS avg_speed_kmh, ROUND(AVG(Actual_Repair_Cost_INR), 2) AS avg_cost_inr FROM telematics_claims GROUP BY g_force_band ORDER BY g_force_band;"},
    {"id":"Q10","category":"Crash context","title":"Does weather condition correspond to different claim costs?","business_value":"Compare descriptive patterns across weather conditions.","sql":"SELECT Weather_Condition, COUNT(*) AS claim_count, ROUND(AVG(Actual_Repair_Cost_INR), 2) AS avg_cost_inr, ROUND(AVG(Speed_At_Impact_kmh), 2) AS avg_speed_kmh FROM telematics_claims GROUP BY Weather_Condition ORDER BY claim_count DESC;"},
    {"id":"Q11","category":"Crash context","title":"Which road types have the highest average repair cost?","business_value":"Inform road-context segmentation and severity reporting.","sql":"SELECT Road_Type, COUNT(*) AS claim_count, ROUND(AVG(Actual_Repair_Cost_INR), 2) AS avg_cost_inr, ROUND(AVG(Speed_At_Impact_kmh), 2) AS avg_speed_kmh FROM telematics_claims GROUP BY Road_Type ORDER BY avg_cost_inr DESC;"},
    {"id":"Q12","category":"Geography","title":"Which crash areas carry the largest repair spend?","business_value":"Compare volume and financial burden by simulated area.","sql":"SELECT Crash_Area, COUNT(*) AS claim_count, ROUND(SUM(Actual_Repair_Cost_INR), 2) AS total_cost_inr, ROUND(AVG(Actual_Repair_Cost_INR), 2) AS avg_cost_inr FROM telematics_claims GROUP BY Crash_Area ORDER BY total_cost_inr DESC;"},
    {"id":"Q13","category":"Time trends","title":"How many claims occur each month?","business_value":"Provide a monthly operational workload baseline.","sql":"SELECT strftime('%Y-%m', AccidentDate) AS accident_month, COUNT(*) AS claim_count, ROUND(SUM(Actual_Repair_Cost_INR), 2) AS total_cost_inr, ROUND(AVG(Actual_Repair_Cost_INR), 2) AS avg_cost_inr FROM telematics_claims GROUP BY accident_month ORDER BY accident_month;"},
    {"id":"Q14","category":"Time trends","title":"How does monthly claim count change from the prior month?","business_value":"Spot volume changes with a window function.","sql":"WITH monthly AS (SELECT strftime('%Y-%m', AccidentDate) AS accident_month, COUNT(*) AS claim_count FROM telematics_claims GROUP BY accident_month) SELECT accident_month, claim_count, LAG(claim_count) OVER (ORDER BY accident_month) AS prior_month_claims, claim_count - LAG(claim_count) OVER (ORDER BY accident_month) AS month_over_month_change FROM monthly ORDER BY accident_month;"},
    {"id":"Q15","category":"Time trends","title":"Are claims more common on weekdays or weekends?","business_value":"Support staffing patterns without inferring causation.","sql":"SELECT CASE WHEN CAST(strftime('%w', AccidentDate) AS INTEGER) IN (0,6) THEN 'Weekend' ELSE 'Weekday' END AS day_type, COUNT(*) AS claim_count, ROUND(AVG(Actual_Repair_Cost_INR), 2) AS avg_cost_inr FROM telematics_claims GROUP BY day_type;"},
    {"id":"Q16","category":"Time trends","title":"At what hours are incidents most frequent?","business_value":"Understand simulated hour-of-day workload peaks.","sql":"SELECT CAST(strftime('%H', AccidentDate) AS INTEGER) AS accident_hour, COUNT(*) AS claim_count, ROUND(AVG(Actual_Repair_Cost_INR), 2) AS avg_cost_inr FROM telematics_claims GROUP BY accident_hour ORDER BY claim_count DESC;"},
    {"id":"Q17","category":"Vehicle age","title":"How does vehicle age relate to repair cost?","business_value":"Segment cost patterns by vehicle age at incident time.","sql":"SELECT CASE WHEN CAST(strftime('%Y', AccidentDate) AS INTEGER) - Model_Year < 3 THEN '0-2 years' WHEN CAST(strftime('%Y', AccidentDate) AS INTEGER) - Model_Year < 7 THEN '3-6 years' WHEN CAST(strftime('%Y', AccidentDate) AS INTEGER) - Model_Year < 12 THEN '7-11 years' ELSE '12+ years' END AS vehicle_age_band, COUNT(*) AS claim_count, ROUND(AVG(Actual_Repair_Cost_INR), 2) AS avg_cost_inr FROM telematics_claims GROUP BY vehicle_age_band ORDER BY vehicle_age_band;"},
    {"id":"Q18","category":"Cost outliers","title":"What are the 15 most expensive claims?","business_value":"Create a review queue of highest-value repair events.","sql":"SELECT ClaimID, AccidentDate, Vehicle_Brand, Crash_Area, Speed_At_Impact_kmh, G_Force_Impact, Airbag_Deployed, Actual_Repair_Cost_INR FROM telematics_claims ORDER BY Actual_Repair_Cost_INR DESC LIMIT 15;"},
    {"id":"Q19","category":"Cost outliers","title":"Which claims are above average cost by more than two standard deviations?","business_value":"Illustrate a transparent statistical outlier rule.","sql":"WITH stats AS (SELECT AVG(Actual_Repair_Cost_INR) AS avg_cost, (AVG(Actual_Repair_Cost_INR * Actual_Repair_Cost_INR) - AVG(Actual_Repair_Cost_INR) * AVG(Actual_Repair_Cost_INR)) AS var_cost FROM telematics_claims) SELECT c.ClaimID, c.Vehicle_Brand, c.Speed_At_Impact_kmh, c.G_Force_Impact, c.Actual_Repair_Cost_INR, ROUND(s.avg_cost, 2) AS portfolio_avg_cost FROM telematics_claims c CROSS JOIN stats s WHERE c.Actual_Repair_Cost_INR > s.avg_cost + 2 * sqrt(MAX(s.var_cost, 0)) ORDER BY c.Actual_Repair_Cost_INR DESC;"},
    {"id":"Q20","category":"Vehicle patterns","title":"Which vehicles have the most recorded incidents?","business_value":"Identify repeated synthetic VehicleID appearances for further context.","sql":"SELECT VehicleID, COUNT(*) AS incident_count, ROUND(SUM(Actual_Repair_Cost_INR), 2) AS total_repair_cost_inr, ROUND(AVG(Actual_Repair_Cost_INR), 2) AS avg_repair_cost_inr FROM telematics_claims GROUP BY VehicleID HAVING COUNT(*) > 1 ORDER BY incident_count DESC, total_repair_cost_inr DESC LIMIT 20;"},
    {"id":"Q21","category":"Vehicle patterns","title":"What is the average cost for repeat versus single-incident vehicles?","business_value":"Compare groups while noting repeat identity is simulated.","sql":"WITH vehicle_counts AS (SELECT VehicleID, COUNT(*) AS claim_count FROM telematics_claims GROUP BY VehicleID) SELECT CASE WHEN v.claim_count > 1 THEN 'Repeat vehicle' ELSE 'Single recorded incident' END AS vehicle_group, COUNT(*) AS claims, ROUND(AVG(c.Actual_Repair_Cost_INR), 2) AS avg_cost_inr FROM telematics_claims c JOIN vehicle_counts v ON c.VehicleID = v.VehicleID GROUP BY vehicle_group;"},
    {"id":"Q22","category":"Crash severity","title":"How is crash severity distributed by brand?","business_value":"Separate brand volume from severity mix.","sql":"SELECT Vehicle_Brand, CASE WHEN Speed_At_Impact_kmh < 25 THEN 'Low' WHEN Speed_At_Impact_kmh < 50 THEN 'Moderate' WHEN Speed_At_Impact_kmh < 80 THEN 'High' ELSE 'Very high' END AS severity_band, COUNT(*) AS claim_count FROM telematics_claims GROUP BY Vehicle_Brand, severity_band ORDER BY Vehicle_Brand, claim_count DESC;"},
    {"id":"Q23","category":"Crash severity","title":"How does airbag deployment rate vary by speed band?","business_value":"Check whether the generated safety signal behaves plausibly.","sql":"SELECT CASE WHEN Speed_At_Impact_kmh < 25 THEN 'Low (<25)' WHEN Speed_At_Impact_kmh < 50 THEN 'Moderate (25-49)' WHEN Speed_At_Impact_kmh < 80 THEN 'High (50-79)' ELSE 'Very high (80+)' END AS speed_band, COUNT(*) AS claim_count, ROUND(100.0 * AVG(Airbag_Deployed), 2) AS airbag_deployment_pct FROM telematics_claims GROUP BY speed_band ORDER BY speed_band;"},
    {"id":"Q24","category":"Crash severity","title":"What are average speed and costs by impact point?","business_value":"Compare the mix of impact zones and associated loss amounts.","sql":"SELECT Impact_Point, COUNT(*) AS claim_count, ROUND(AVG(Speed_At_Impact_kmh), 2) AS avg_speed_kmh, ROUND(AVG(G_Force_Impact), 2) AS avg_g_force, ROUND(AVG(Actual_Repair_Cost_INR), 2) AS avg_cost_inr FROM telematics_claims GROUP BY Impact_Point ORDER BY avg_speed_kmh DESC;"},
    {"id":"Q25","category":"Crash severity","title":"How do costs vary across speed quartiles?","business_value":"Compare relative cost progression using NTILE windowing.","sql":"WITH bands AS (SELECT *, NTILE(4) OVER (ORDER BY Speed_At_Impact_kmh) AS speed_quartile FROM telematics_claims) SELECT speed_quartile, COUNT(*) AS claim_count, ROUND(MIN(Speed_At_Impact_kmh), 2) AS min_speed, ROUND(MAX(Speed_At_Impact_kmh), 2) AS max_speed, ROUND(AVG(Actual_Repair_Cost_INR), 2) AS avg_cost_inr FROM bands GROUP BY speed_quartile ORDER BY speed_quartile;"},
    {"id":"Q26","category":"Crash severity","title":"Which features accompany the highest repair costs?","business_value":"Summarize severity indicators alongside claim cost.","sql":"SELECT CASE WHEN Airbag_Deployed = 1 THEN 'Airbag deployed' ELSE 'No airbag deployment' END AS airbag_status, Impact_Point, COUNT(*) AS claim_count, ROUND(AVG(Speed_At_Impact_kmh), 2) AS avg_speed_kmh, ROUND(AVG(G_Force_Impact), 2) AS avg_g_force, ROUND(AVG(Actual_Repair_Cost_INR), 2) AS avg_cost_inr FROM telematics_claims GROUP BY airbag_status, Impact_Point ORDER BY avg_cost_inr DESC;"},
    {"id":"Q27","category":"Cost distribution","title":"What is the repair-cost distribution by percentile group?","business_value":"Expose long-tail cost behavior rather than relying only on averages.","sql":"WITH ranked AS (SELECT Actual_Repair_Cost_INR, NTILE(10) OVER (ORDER BY Actual_Repair_Cost_INR) AS cost_decile FROM telematics_claims) SELECT cost_decile, COUNT(*) AS claim_count, ROUND(MIN(Actual_Repair_Cost_INR), 2) AS min_cost_inr, ROUND(MAX(Actual_Repair_Cost_INR), 2) AS max_cost_inr, ROUND(AVG(Actual_Repair_Cost_INR), 2) AS avg_cost_inr FROM ranked GROUP BY cost_decile ORDER BY cost_decile;"},
    {"id":"Q28","category":"Time trends","title":"How do claim volume and average cost change by quarter?","business_value":"Provide a quarterly view for staffing and trend discussion.","sql":"SELECT strftime('%Y', AccidentDate) AS accident_year, CAST((CAST(strftime('%m', AccidentDate) AS INTEGER) + 2) / 3 AS INTEGER) AS accident_quarter, COUNT(*) AS claim_count, ROUND(AVG(Actual_Repair_Cost_INR), 2) AS avg_cost_inr, ROUND(SUM(Actual_Repair_Cost_INR), 2) AS total_cost_inr FROM telematics_claims GROUP BY accident_year, accident_quarter ORDER BY accident_year, accident_quarter;"},
    {"id":"Q29","category":"Time trends","title":"Are weekend incidents more expensive after grouping by impact point?","business_value":"Check whether a simple aggregate is being driven by crash mix.","sql":"SELECT CASE WHEN CAST(strftime('%w', AccidentDate) AS INTEGER) IN (0,6) THEN 'Weekend' ELSE 'Weekday' END AS day_type, Impact_Point, COUNT(*) AS claim_count, ROUND(AVG(Actual_Repair_Cost_INR), 2) AS avg_cost_inr FROM telematics_claims GROUP BY day_type, Impact_Point ORDER BY day_type, avg_cost_inr DESC;"},
    {"id":"Q30","category":"Vehicle age","title":"What are claim counts and costs by vehicle-age band and brand?","business_value":"Support segment-specific repair-cost benchmarking.","sql":"SELECT Vehicle_Brand, CASE WHEN CAST(strftime('%Y', AccidentDate) AS INTEGER) - Model_Year < 3 THEN '0-2 years' WHEN CAST(strftime('%Y', AccidentDate) AS INTEGER) - Model_Year < 7 THEN '3-6 years' WHEN CAST(strftime('%Y', AccidentDate) AS INTEGER) - Model_Year < 12 THEN '7-11 years' ELSE '12+ years' END AS vehicle_age_band, COUNT(*) AS claim_count, ROUND(AVG(Actual_Repair_Cost_INR), 2) AS avg_cost_inr FROM telematics_claims GROUP BY Vehicle_Brand, vehicle_age_band HAVING COUNT(*) >= 5 ORDER BY Vehicle_Brand, avg_cost_inr DESC;"},
    {"id":"Q31","category":"Garage network","title":"How many garages specialize in each vehicle brand?","business_value":"Measure supply depth by make.","sql":"SELECT Brand_Specialization AS Vehicle_Brand, COUNT(*) AS garage_count, SUM(CASE WHEN Parts_Available = 1 THEN 1 ELSE 0 END) AS in_stock_garages, SUM(CASE WHEN Preferred_Partner = 1 THEN 1 ELSE 0 END) AS preferred_garages FROM partner_garages GROUP BY Brand_Specialization ORDER BY garage_count DESC;"},
    {"id":"Q32","category":"Garage network","title":"What is parts availability by brand?","business_value":"Identify makes where routing choices may be constrained.","sql":"SELECT Brand_Specialization AS Vehicle_Brand, COUNT(*) AS garage_count, ROUND(100.0 * AVG(CASE WHEN Parts_Available = 1 THEN 1.0 ELSE 0.0 END), 2) AS in_stock_pct, SUM(CASE WHEN Parts_Available = 0 THEN 1 ELSE 0 END) AS out_of_stock_garages FROM partner_garages GROUP BY Brand_Specialization ORDER BY in_stock_pct;"},
    {"id":"Q33","category":"Garage network","title":"Which areas have the largest preferred-partner share?","business_value":"Review network composition by area.","sql":"SELECT Area, COUNT(*) AS garage_count, SUM(CASE WHEN Preferred_Partner = 1 THEN 1 ELSE 0 END) AS preferred_count, ROUND(100.0 * AVG(CASE WHEN Preferred_Partner = 1 THEN 1.0 ELSE 0.0 END), 2) AS preferred_share_pct FROM partner_garages GROUP BY Area ORDER BY preferred_share_pct DESC;"},
    {"id":"Q34","category":"Garage network","title":"Which areas have the greatest daily service capacity?","business_value":"Compare total intake capacity across simulated service areas.","sql":"SELECT Area, COUNT(*) AS garage_count, SUM(Daily_Service_Capacity) AS total_daily_capacity, ROUND(AVG(Daily_Service_Capacity), 1) AS avg_capacity_per_garage FROM partner_garages GROUP BY Area ORDER BY total_daily_capacity DESC;"},
    {"id":"Q35","category":"Garage network","title":"Which garage-specialization groups have longer turnaround?","business_value":"Find potential cycle-time bottlenecks in the simulated network.","sql":"SELECT Brand_Specialization AS Vehicle_Brand, COUNT(*) AS garage_count, ROUND(AVG(Avg_Repair_Turnaround_Days), 2) AS avg_turnaround_days, ROUND(MIN(Avg_Repair_Turnaround_Days), 2) AS min_turnaround_days, ROUND(MAX(Avg_Repair_Turnaround_Days), 2) AS max_turnaround_days FROM partner_garages GROUP BY Brand_Specialization ORDER BY avg_turnaround_days DESC;"},
    {"id":"Q36","category":"Garage network","title":"How do simulated labor rates vary by area?","business_value":"Review cost-of-service differences in the garage network.","sql":"SELECT Area, COUNT(*) AS garage_count, ROUND(AVG(Labor_Rate_INR_Per_Hour), 2) AS avg_labor_rate_inr_hour, MIN(Labor_Rate_INR_Per_Hour) AS min_labor_rate, MAX(Labor_Rate_INR_Per_Hour) AS max_labor_rate FROM partner_garages GROUP BY Area ORDER BY avg_labor_rate_inr_hour DESC;"},
    {"id":"Q37","category":"Garage network","title":"Which vehicle brands have out-of-stock garages?","business_value":"Plan spare-parts availability improvements.","sql":"SELECT Brand_Specialization AS Vehicle_Brand, COUNT(*) AS garage_count, SUM(CASE WHEN Parts_Available = 0 THEN 1 ELSE 0 END) AS out_of_stock_count, ROUND(100.0 * AVG(CASE WHEN Parts_Available = 0 THEN 1.0 ELSE 0.0 END), 2) AS out_of_stock_pct FROM partner_garages GROUP BY Brand_Specialization HAVING out_of_stock_count > 0 ORDER BY out_of_stock_pct DESC;"},
    {"id":"Q38","category":"Garage coverage","title":"Is garage supply proportional to the claim mix by brand?","business_value":"Compare demand share with eligible garage supply share.","sql":"WITH demand AS (SELECT Vehicle_Brand, COUNT(*) AS claim_count FROM telematics_claims GROUP BY Vehicle_Brand), supply AS (SELECT Brand_Specialization AS Vehicle_Brand, SUM(CASE WHEN Parts_Available = 1 THEN 1 ELSE 0 END) AS eligible_garages FROM partner_garages GROUP BY Brand_Specialization), totals AS (SELECT SUM(claim_count) AS total_claims FROM demand), total_supply AS (SELECT SUM(eligible_garages) AS total_garages FROM supply) SELECT d.Vehicle_Brand, d.claim_count, s.eligible_garages, ROUND(100.0 * d.claim_count / t.total_claims, 2) AS demand_share_pct, ROUND(100.0 * s.eligible_garages / ts.total_garages, 2) AS eligible_supply_share_pct, ROUND(1.0 * d.claim_count / NULLIF(s.eligible_garages, 0), 2) AS claims_per_eligible_garage FROM demand d JOIN supply s ON d.Vehicle_Brand = s.Vehicle_Brand CROSS JOIN totals t CROSS JOIN total_supply ts ORDER BY claims_per_eligible_garage DESC;"},
    {"id":"Q39","category":"Garage coverage","title":"Which brands have the fewest in-stock preferred garages?","business_value":"Locate potential preferred-network coverage gaps.","sql":"SELECT Brand_Specialization AS Vehicle_Brand, SUM(CASE WHEN Parts_Available = 1 AND Preferred_Partner = 1 THEN 1 ELSE 0 END) AS preferred_in_stock_garages, SUM(CASE WHEN Parts_Available = 1 THEN 1 ELSE 0 END) AS all_in_stock_garages FROM partner_garages GROUP BY Brand_Specialization ORDER BY preferred_in_stock_garages ASC, all_in_stock_garages ASC;"},
    {"id":"Q40","category":"Garage coverage","title":"What is the average capacity-to-turnaround profile by area?","business_value":"Compare network capacity with simulated repair duration.","sql":"SELECT Area, COUNT(*) AS garage_count, ROUND(AVG(Daily_Service_Capacity), 2) AS avg_daily_capacity, ROUND(AVG(Avg_Repair_Turnaround_Days), 2) AS avg_turnaround_days, ROUND(AVG(Daily_Service_Capacity / NULLIF(Avg_Repair_Turnaround_Days, 0)), 2) AS capacity_per_turnaround_day FROM partner_garages GROUP BY Area ORDER BY capacity_per_turnaround_day DESC;"},
    {"id":"Q41","category":"Routing operations","title":"How many routes used the preferred-partner fallback?","business_value":"Show whether routing had to relax the preferred-partner condition.","sql":"SELECT Preferred_Fallback_Used, COUNT(*) AS claim_count, ROUND(100.0 * COUNT(*) / (SELECT COUNT(*) FROM garage_routing), 2) AS share_pct FROM garage_routing GROUP BY Preferred_Fallback_Used;"},
    {"id":"Q42","category":"Routing operations","title":"What are average route distance and cycle time by brand?","business_value":"Compare routing effort across vehicle makes.","sql":"SELECT Vehicle_Brand, COUNT(*) AS routed_claims, ROUND(AVG(Recommended_Garage_Distance_km), 2) AS avg_distance_km, ROUND(AVG(Recommended_Garage_Travel_Minutes), 1) AS avg_travel_minutes, ROUND(AVG(Recommended_Garage_Turnaround_Days), 2) AS avg_turnaround_days, ROUND(AVG(Recommended_Garage_Est_Cycle_Hours), 2) AS avg_estimated_cycle_hours FROM garage_routing GROUP BY Vehicle_Brand ORDER BY avg_estimated_cycle_hours DESC;"},
    {"id":"Q43","category":"Routing operations","title":"Which garages receive the most routing recommendations?","business_value":"Show how the routing heuristic distributes simulated work.","sql":"SELECT r.Recommended_GarageID, g.Garage_Name, g.Area, g.Brand_Specialization, COUNT(*) AS recommended_claims, g.Daily_Service_Capacity, ROUND(1.0 * COUNT(*) / g.Daily_Service_Capacity, 2) AS claims_per_capacity_unit_proxy FROM garage_routing r JOIN partner_garages g ON r.Recommended_GarageID = g.GarageID GROUP BY r.Recommended_GarageID, g.Garage_Name, g.Area, g.Brand_Specialization, g.Daily_Service_Capacity ORDER BY recommended_claims DESC LIMIT 20;"},
    {"id":"Q44","category":"Routing operations","title":"Which crash areas have the longest average garage route?","business_value":"Identify simulated geography with more travel burden.","sql":"SELECT Crash_Area, COUNT(*) AS routed_claims, ROUND(AVG(Recommended_Garage_Distance_km), 2) AS avg_distance_km, ROUND(MAX(Recommended_Garage_Distance_km), 2) AS max_distance_km, ROUND(AVG(Recommended_Garage_Travel_Minutes), 1) AS avg_travel_minutes FROM garage_routing GROUP BY Crash_Area ORDER BY avg_distance_km DESC;"},
    {"id":"Q45","category":"Routing operations","title":"How often is the balanced recommendation farther than the nearest eligible garage?","business_value":"Quantify the distance-versus-turnaround/capacity trade-off.","sql":"SELECT COUNT(*) AS claims_routed, SUM(CASE WHEN Recommended_GarageID <> Nearest_Eligible_GarageID THEN 1 ELSE 0 END) AS recommendation_differs_from_nearest, ROUND(100.0 * AVG(CASE WHEN Recommended_GarageID <> Nearest_Eligible_GarageID THEN 1.0 ELSE 0.0 END), 2) AS changed_recommendation_pct, ROUND(AVG(Recommended_Garage_Distance_km - Nearest_Eligible_Garage_Distance_km), 3) AS avg_extra_distance_km FROM garage_routing;"},
    {"id":"Q46","category":"Routing operations","title":"How many claims are routed beyond 10 kilometres?","business_value":"Find longer-distance routing cases for manual review.","sql":"SELECT COUNT(*) AS claims_over_10km, ROUND(100.0 * COUNT(*) / (SELECT COUNT(*) FROM garage_routing), 2) AS share_pct, ROUND(AVG(Recommended_Garage_Distance_km), 2) AS avg_distance_over_10km FROM garage_routing WHERE Recommended_Garage_Distance_km > 10;"},
    {"id":"Q47","category":"Routing operations","title":"What is routing distance by garage policy?","business_value":"Compare preferred-only routing with fallback scenarios.","sql":"SELECT Candidate_Policy, COUNT(*) AS claims, ROUND(AVG(Recommended_Garage_Distance_km), 2) AS avg_distance_km, ROUND(AVG(Recommended_Garage_Turnaround_Days), 2) AS avg_turnaround_days, ROUND(AVG(Recommended_Garage_Est_Cycle_Hours), 2) AS avg_cycle_hours FROM garage_routing GROUP BY Candidate_Policy ORDER BY claims DESC;"},
    {"id":"Q48","category":"Routing operations","title":"Where are route recommendation counts concentrated?","business_value":"Examine routing allocations by area and garage specialization.","sql":"SELECT Crash_Area, Recommended_Garage_Area, COUNT(*) AS route_count, ROUND(AVG(Recommended_Garage_Distance_km), 2) AS avg_distance_km FROM garage_routing GROUP BY Crash_Area, Recommended_Garage_Area ORDER BY route_count DESC LIMIT 25;"},
    {"id":"Q49","category":"Repair model","title":"What is holdout prediction error by impact-speed band?","business_value":"Check where model performance varies with crash severity.","sql":"SELECT CASE WHEN Speed_At_Impact_kmh < 25 THEN 'Low (<25)' WHEN Speed_At_Impact_kmh < 50 THEN 'Moderate (25-49)' WHEN Speed_At_Impact_kmh < 80 THEN 'High (50-79)' ELSE 'Very high (80+)' END AS speed_band, COUNT(*) AS holdout_claims, ROUND(AVG(Absolute_Error_INR), 2) AS mae_inr, ROUND(AVG(Actual_Repair_Cost_INR), 2) AS avg_actual_cost_inr, ROUND(AVG(Predicted_Repair_Cost_INR), 2) AS avg_predicted_cost_inr FROM holdout_predictions GROUP BY speed_band ORDER BY speed_band;"},
    {"id":"Q50","category":"Repair model","title":"Which brands have the largest holdout prediction errors?","business_value":"Identify vehicle makes where repair-cost estimates need caution.","sql":"SELECT Vehicle_Brand, COUNT(*) AS holdout_claims, ROUND(AVG(Absolute_Error_INR), 2) AS mae_inr, ROUND(AVG(Actual_Repair_Cost_INR), 2) AS avg_actual_cost_inr, ROUND(AVG(Predicted_Repair_Cost_INR), 2) AS avg_predicted_cost_inr FROM holdout_predictions GROUP BY Vehicle_Brand HAVING COUNT(*) >= 5 ORDER BY mae_inr DESC;"},
    {"id":"Q51","category":"Repair model","title":"What are the most poorly predicted holdout claims?","business_value":"Create examples for error analysis, not automatic claim denials.","sql":"SELECT ClaimID, AccidentDate, Vehicle_Brand, Speed_At_Impact_kmh, G_Force_Impact, Airbag_Deployed, Actual_Repair_Cost_INR, Predicted_Repair_Cost_INR, Absolute_Error_INR FROM holdout_predictions ORDER BY Absolute_Error_INR DESC LIMIT 20;"},
    {"id":"Q52","category":"Repair model","title":"Does prediction bias differ across vehicle makes?","business_value":"Inspect signed errors for systematic over- or underprediction.","sql":"SELECT Vehicle_Brand, COUNT(*) AS holdout_claims, ROUND(AVG(Signed_Error_INR), 2) AS mean_signed_error_inr, ROUND(AVG(Absolute_Error_INR), 2) AS mean_absolute_error_inr FROM holdout_predictions GROUP BY Vehicle_Brand HAVING COUNT(*) >= 5 ORDER BY ABS(AVG(Signed_Error_INR)) DESC;"},
    {"id":"Q53","category":"Repair model","title":"How close are actual and predicted costs by impact point?","business_value":"Compare error patterns across collision zones.","sql":"SELECT Impact_Point, COUNT(*) AS holdout_claims, ROUND(AVG(Actual_Repair_Cost_INR), 2) AS avg_actual_cost_inr, ROUND(AVG(Predicted_Repair_Cost_INR), 2) AS avg_predicted_cost_inr, ROUND(AVG(Absolute_Error_INR), 2) AS mae_inr FROM holdout_predictions GROUP BY Impact_Point ORDER BY mae_inr DESC;"},
    {"id":"Q54","category":"Repair model","title":"How does model MAE compare to a training-period mean baseline by brand?","business_value":"Compare predictions relative to the mean cost in the training period.","sql":"SELECT Vehicle_Brand, COUNT(*) AS holdout_claims, ROUND(AVG(Absolute_Error_INR), 2) AS model_mae_inr, ROUND(AVG(ABS(Actual_Repair_Cost_INR - (SELECT AVG(Actual_Repair_Cost_INR) FROM telematics_claims WHERE AccidentDate < (SELECT MIN(AccidentDate) FROM holdout_predictions)))), 2) AS benchmark_mae_inr FROM holdout_predictions GROUP BY Vehicle_Brand HAVING COUNT(*) >= 5 ORDER BY model_mae_inr DESC;"},
    {"id":"Q55","category":"Executive decisions","title":"Which brands combine high demand with low preferred in-stock coverage?","business_value":"Create a prioritized network improvement view.","sql":"WITH demand AS (SELECT Vehicle_Brand, COUNT(*) AS claim_count, AVG(Actual_Repair_Cost_INR) AS avg_cost FROM telematics_claims GROUP BY Vehicle_Brand), network AS (SELECT Brand_Specialization AS Vehicle_Brand, SUM(CASE WHEN Parts_Available = 1 AND Preferred_Partner = 1 THEN 1 ELSE 0 END) AS preferred_stock_garages, SUM(CASE WHEN Parts_Available = 1 THEN 1 ELSE 0 END) AS all_stock_garages FROM partner_garages GROUP BY Brand_Specialization) SELECT d.Vehicle_Brand, d.claim_count, ROUND(d.avg_cost, 2) AS avg_cost_inr, n.preferred_stock_garages, n.all_stock_garages, ROUND(1.0 * d.claim_count / NULLIF(n.preferred_stock_garages, 0), 2) AS claims_per_preferred_stock_garage FROM demand d JOIN network n ON d.Vehicle_Brand = n.Vehicle_Brand ORDER BY claims_per_preferred_stock_garage DESC;"},
]
